require "rails_helper"

RSpec.describe Timekeeping::MetricsClient do
  # "The task gathers real signals: ... from its `GET /internal/v1/metrics` endpoint, read with the service identity."
  it "reads the metrics endpoint with the service token and refuses a body with non-integer counts without echoing the token" do
    token = SecureRandom.hex(24)
    env_before = ENV.to_h.slice("TIMEKEEPING_BASE_URL", "TIMEKEEPING_SERVICE_TOKEN")
    ENV["TIMEKEEPING_BASE_URL"] = "http://timekeeping.test"
    ENV["TIMEKEEPING_SERVICE_TOKEN"] = token
    body = {
      "latency_bucket_bounds_ms" => [25, 50, 100, 200, 300, 500, 1000, 2500, 5000],
      "overflow_bucket" => "inf",
      "total_field" => "writes + reference_unavailable",
      "companies" => [{ "company_id" => 7, "windows" => [{
        "window_start" => "2026-03-03T12:00:00Z", "writes" => 10, "reference_unavailable" => 1,
        "stale_generation" => 0, "latency_ms_sum" => 200, "latency_ms_buckets" => { "25" => 11 }
      }] }]
    }
    good = stub_request(:get, "http://timekeeping.test/internal/v1/metrics")
      .with(headers: { "Authorization" => "Bearer #{token}" })
      .to_return(status: 200, body: JSON.generate(body), headers: { "Content-Type" => "application/json" })

    expect(described_class.configured.fetch).to eq(body)
    expect(good).to have_been_requested.once

    bad = body.deep_dup
    bad["companies"][0]["windows"][0]["writes"] = "10"
    stub_request(:get, "http://timekeeping.test/internal/v1/metrics").to_return(status: 200, body: JSON.generate(bad))

    expect { described_class.configured.fetch }.to raise_error(Timekeeping::MetricsClient::Unavailable) { |error|
      expect(error.message).not_to include(token)
    }
  ensure
    %w[TIMEKEEPING_BASE_URL TIMEKEEPING_SERVICE_TOKEN].each { |key| ENV[key] = env_before[key] }
  end
end

